<body>
  <div class="shell" data-harness-ready="true">
    <aside>
      <div class="brand"><span class="mark">⌑</span> Keepsake</div>
      <nav>
        <a class="active" href="#">▤ &nbsp;All bookmarks</a>
        <a href="#">◷ &nbsp;Read later</a>
        <a href="#"># &nbsp;Tags</a>
      </nav>
    </aside>
    <main>
      <h1>Your bookmarks</h1>
      <p class="lede">Save the useful corners of the web.</p>
      <section id="searchbox" class="searchbox" aria-label="Search bookmarks">
        <div class="search-wrap"><input id="search" aria-label="Search bookmarks" placeholder="Search bookmarks…" autocomplete="off"></div>
        <div id="filter-note" class="filter-note"><span>Showing tag: <strong id="filter-tag"></strong></span><button id="clear-filter" aria-label="Clear tag filter">×</button></div>
      </section>
      <section class="savebox" aria-label="Save a bookmark">
        <div class="row">
          <input id="url" aria-label="Web address" placeholder="Paste a web address…" autocomplete="off">
          <button id="save" disabled>Save bookmark</button>
        </div>
        <div id="status" class="status">Paste an address to get started.</div>
        <div id="preview" class="preview">
          <strong id="preview-title"></strong>
          <p id="preview-description"></p>
          <div class="tag-panel">
            <label class="tag-label" for="chip-input">Tags</label>
            <div class="tag-input-wrap"><span class="chip">web design ×</span><input id="chip-input" placeholder="Add a tag…"></div>
            <div id="tag-suggestions" class="tag-suggestions">
              <button id="tag-suggestion" class="tag-suggestion"><span>reference</span><small>Existing tag · Enter ↵</small></button>
            </div>
          </div>
        </div>
      </section>
      <div class="section-head"><h2>All bookmarks</h2><span id="count" class="count">0 bookmarks</span></div>
      <div id="list"><div class="empty">Your saved links will appear here.</div></div>
    </main>
  </div>
  <script>
    const url = document.querySelector('#url');
    const save = document.querySelector('#save');
    const status = document.querySelector('#status');
    const preview = document.querySelector('#preview');
    const list = document.querySelector('#list');
    const count = document.querySelector('#count');
    const search = document.querySelector('#search');
    let timer;
    let details = null;
    const chipInput=document.querySelector('#chip-input');
    const tagSuggestions=document.querySelector('#tag-suggestions');
    function addChip(value) {
        if (!value.trim()) return;
        const chip=document.createElement('span'); chip.className='chip'; chip.textContent=value.trim().toLowerCase()+' ×';
        chipInput.before(chip); chipInput.value=''; tagSuggestions.classList.remove('show');
    }
    chipInput.addEventListener('input', event => {
      const typed=event.target.value.trim().toLowerCase();
      tagSuggestions.classList.toggle('show', typed.length > 0 && 'reference'.startsWith(typed));
    });
    chipInput.addEventListener('keydown', event => {
      if (event.key === 'Enter' && event.target.value.trim()) {
        event.preventDefault();
        addChip(tagSuggestions.classList.contains('show') ? 'reference' : event.target.value);
      }
    });
    document.querySelector('#tag-suggestion').addEventListener('click', event => { event.preventDefault(); addChip('reference'); });
    const known = {
      'developer.mozilla.org': ['CSS grid layout - CSS | MDN', 'CSS grid layout is a two-dimensional layout system for the web. It lets you arrange content in rows and columns.'],
      'www.nationalgeographic.com': ['National Geographic', 'Explore the world through science, history, nature, and culture.'],
      'en.wikipedia.org': ['Wikipedia, the free encyclopedia', 'The free encyclopedia that anyone can edit.']
    };
    const exampleBookmarks = [
      { title:'CSS grid layout - CSS | MDN', description:'A complete guide to two-dimensional layouts with rows and columns.', site:'developer.mozilla.org', tags:['web design','reference'] },
      { title:'The Marginalian', description:'Long-form reflections on books, art, philosophy, and what makes a meaningful life.', site:'themarginalian.org', tags:['reading','essays'] },
      { title:'A guide to better sourdough bread', description:'Practical notes on starters, fermentation, shaping, and baking.', site:'example.com', tags:['cooking','read later'] },
      { title:'Inclusive Components', description:'Accessible interface patterns, with practical examples and thoughtful explanations.', site:'inclusive-components.design', tags:['accessibility','web design'] }
    ];
    function renderExamples(items) {
      list.innerHTML=items.length ? items.map(item => `<article class="card"><a href="#">${item.title}</a><p>${item.description}</p><span class="domain">${item.site}</span><div class="saved-tags">${item.tags.map(tag => `<button class="chip" data-tag="${tag}">${tag}</button>`).join('')}</div></article>`).join('') : '<div class="empty">No bookmarks match your search.</div>';
      count.textContent=`${items.length} bookmark${items.length === 1 ? '' : 's'}`;
    }
    if (new URLSearchParams(location.search).get('view') === 'search') {
      document.querySelector('.savebox').style.display='none';
      document.querySelector('#searchbox').style.display='block';
      document.querySelector('.lede').textContent='Find anything you saved.';
      renderExamples(exampleBookmarks);
      search.addEventListener('input', () => {
        document.querySelector('#filter-note').classList.remove('show');
        const term=search.value.trim().toLowerCase();
        renderExamples(exampleBookmarks.filter(item => [item.title, item.description, ...item.tags].some(value => value.toLowerCase().includes(term))));
      });
      list.addEventListener('click', event => {
        const tag=event.target.closest('[data-tag]')?.dataset.tag;
        if (!tag) return;
        search.value=''; document.querySelector('#filter-tag').textContent=tag;
        document.querySelector('#filter-note').classList.add('show');
        renderExamples(exampleBookmarks.filter(item => item.tags.includes(tag)));
      });
      document.querySelector('#clear-filter').addEventListener('click', () => {
        document.querySelector('#filter-note').classList.remove('show'); renderExamples(exampleBookmarks);
      });
    }
    url.addEventListener('input', () => {
      clearTimeout(timer); details=null; preview.classList.remove('show'); save.disabled=true;
      const value=url.value.trim();
      if (!value) { status.textContent='Paste an address to get started.'; return; }
      status.textContent='Getting page details…';
      timer=setTimeout(() => {
        try {
          const parsed=new URL(value);
          const fallback=[parsed.hostname.replace(/^www\./,''), 'Saved from '+parsed.hostname+'.'];
          details=known[parsed.hostname] || fallback;
          document.querySelector('#preview-title').textContent=details[0];
          document.querySelector('#preview-description').textContent=details[1];
          preview.classList.add('show'); status.textContent='Page details found.'; save.disabled=false;
        } catch { status.textContent='That doesn’t look like a complete web address.'; }
      }, 550);
    });
    save.addEventListener('click', () => {
      if (!details) return;
      const parsed=new URL(url.value.trim());
      const tags=[...document.querySelectorAll('.tag-input-wrap .chip')].map(chip => chip.textContent.replace(/\s*×$/, ''));
      const tagMarkup=tags.map(tag => `<button class="chip" data-tag="${tag}">${tag}</button>`).join('');
      list.innerHTML=`<article class="card"><a href="${parsed.href}" target="_blank" rel="noreferrer">${details[0]}</a><p>${details[1]}</p><span class="domain">${parsed.hostname}</span><div class="saved-tags">${tagMarkup}</div></article>`;
      count.textContent='1 bookmark'; status.textContent='Bookmark saved.'; preview.classList.remove('show');
      url.value=''; save.disabled=true; details=null;
    });
  </script>
